class AbrController:
    def __init__(self, bitrates, safety=0.75):
        self.bitrates = sorted(bitrates)  # e.g. [400k, 800k, 2500k, 6000k]
        self.safety = safety
        self.throughput_ewma = None
        self.last_upshift = 0

    def on_segment_downloaded(self, size_bytes, download_s, buffer_s, now_s):
        inst = (size_bytes * 8) / max(download_s, 0.001)
        alpha = 0.3  # EWMA: smooths noise, slows reaction. Trade-off.
        if self.throughput_ewma is None:
            self.throughput_ewma = inst
        else:
            self.throughput_ewma = alpha * inst + (1 - alpha) * self.throughput_ewma

        # Panic: buffer starving, ignore throughput, drop hard.
        if buffer_s < 4.0:
            return self.bitrates[0]
        # Hold-down: prevent oscillation after an upshift.
        allowed = self.throughput_ewma * self.safety
        candidate = max([b for b in self.bitrates if b < allowed], default=self.bitrates[0])
        current = getattr(self, 'current', self.bitrates[0])
        if candidate > current and (now_s - self.last_upshift) < 8.0:
            return current
        if candidate > current:
            self.last_upshift = now_s
        self.current = candidate
        return candidate
